metrics.workdir_dsl:
workspace "Energy Manager" "A home energy management platform" {
    model {
        homeowner = person "Homeowner" "A homeowner who manages their household's energy use and costs."
        energyManager = softwareSystem "Energy Manager" "A platform for managing a household's energy use and costs, owned and operated by our company."
        smartMeterProvider = softwareSystem "Smart Meter Provider" "An external service, operated by a different organization, that provides live meter readings." "External"

        dashboard = energyManager.container "Dashboard Web App" "A web app where homeowners see their household's consumption and costs. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Web App"
        scheduling = energyManager.container "Scheduling Service" "A service that plans charging and heating. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Service"
        database = energyManager.container "Database" "Stores meter readings and schedules." "Database"

        homeowner -> energyManager "manages household energy use and costs" "HTTPS"
        energyManager -> smartMeterProvider "fetches live meter readings" "HTTPS/JSON"

        homeowner -> dashboard "sees consumption and costs" "HTTPS"
        scheduling -> smartMeterProvider "fetches live meter readings" "HTTPS/JSON"
        scheduling -> database "stores meter readings and schedules" "SQL"
    }

    views {
        systemContext energyManager "systemContext" "System context diagram for Energy Manager" {
            include *
        }
        container energyManager "containers" "Container diagram for Energy Manager" {
            include *
        }
    }
}
